import _defineProperty from "@babel/runtime/helpers/esm/defineProperty";
import Model from 'flarum/common/Model';

/** A saved reply: a common answer staff insert into a ticket reply. */
export default class SupportSavedReply extends Model {
  constructor() {
    super(...arguments);
    _defineProperty(this, "title", Model.attribute('title'));
    _defineProperty(this, "content", Model.attribute('content'));
    _defineProperty(this, "position", Model.attribute('position'));
  }
}
flarum.reg.add('linkrobins-support', 'common/models/SupportSavedReply', SupportSavedReply);